{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 확인한 병목이 인덱스 추가와 조인 정리라는 개선 선택으로 이어졌는지 평가한다. 개선 방법을 택한 근거가 실제 조회 구조와 측정 결과에 맞는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸고, 실행 계획에서 신고 테이블과 판매글 테이블을 매번 전체 조인하는 것을 확인했다.",
          "task": "신고 목록 조회 쿼리에 인덱스를 추가하고 조인 순서를 정리해 조회 시간을 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 조회 구조와 조회 조건이 인덱스 추가 및 조인 정리의 근거가 된 이유를 설명한다.",
          "result": "3.2초에서 0.4초로 줄어든 측정 결과가 개선 선택의 타당성을 뒷받침하는 이유를 설명한다."
        },
        "expectedEvidence": [
          "실행 계획을 보고 인덱스 추가와 조인 정리를 택한 근거",
          "조회 조건과 전체 조인 구조에서 확인한 병목",
          "개선 전후 조회 시간과 그 수치를 비교한 조건"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨을 때, 실행 계획을 보고 인덱스 추가와 조인 정리를 택한 근거는 무엇이었나요?",
      "answerTip": "답을 먼저 말하고 설명을 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 전체 조인이나 조회 조건의 문제를 인덱스 추가와 조인 정리의 선택 근거로 구체적으로 연결한다.",
            "개선 전후 측정값을 비교 조건과 연결해 설명하여 선택한 방법이 병목을 줄였다는 근거를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획에서 발견한 문제를 개선 방법과 연결하지만 어떤 조회 구조가 비용을 키웠는지 설명이 일반적이다.",
            "3.2초에서 0.4초로 줄어든 결과를 근거로 제시하지만 측정 조건이나 개선 선택과의 연결은 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스는 빠르다는 일반론만 말하거나 실행 계획에서 확인한 문제와 무관한 선택 근거를 제시한다.",
            "지원서에 적힌 수정 내용과 시간 수치만 반복하고 해당 방법을 택한 근거를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 추적한 장애 원인이 재발 방지 판단으로 이어졌는지 평가한다. 잠금으로 오류를 고친 것과 별도로 배포 체크리스트에 스케줄러 항목을 넣은 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 간다는 문의를 받았고, 시간순 로그에서 스케줄러가 서버 두 대에서 동시에 실행되는 것을 확인했다.",
          "task": "잠금 키를 두는 방식으로 오류를 고쳤고, 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "로그에서 확인한 중복 실행 원인을 배포 체크리스트의 스케줄러 항목과 연결해 추가 판단의 근거를 설명한다.",
          "result": "잠금 수정과 배포 점검이 각각 어떤 역할을 하며 체크리스트 항목이 같은 장애의 재발 가능성을 줄이는 이유를 설명한다."
        },
        "expectedEvidence": [
          "재발 방지로 배포 체크리스트에 스케줄러 항목을 넣은 근거",
          "서버 두 대의 스케줄러 동시 실행을 보여 준 시간순 로그",
          "잠금 수정과 별도로 배포 점검이 필요하다고 본 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 로그로 추적하셨을 때, 재발 방지로 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "한 사례에 집중해 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행을 체크리스트 항목을 추가한 근거로 구체적으로 연결한다.",
            "잠금으로 당시 오류를 고친 것과 별도로 배포 점검이 같은 원인의 재발을 막는 데 필요한 이유를 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 막으려고 체크리스트에 항목을 넣었다고 답하지만 로그에서 확인한 원인과의 연결은 구체적이지 않다.",
            "수정 후에도 배포 점검이 필요하다는 취지는 설명하지만 점검이 재발 가능성을 줄이는 이유는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 스케줄러 항목을 넣은 근거를 설명하지 못하거나 확인한 장애 원인과 무관한 이유를 제시한다.",
            "잠금 수정 내용만 반복하거나 점검은 중요하다는 일반론만 말해 재발 방지 판단을 드러내지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "여러 요청을 요구사항으로 구체화할 때 포함할 범위와 제외할 범위를 판단할 수 있는지 확인한다. 세탁소 인터뷰 내용을 개발 담당 팀원과 조정한 요구사항 범위에 연결한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 파악한 요청의 목적과 필요성을 요구사항 범위 조정의 근거로 삼은 내용을 설명한다.",
          "result": "설명한 근거가 요구사항 정의서에 포함하거나 제외한 범위와 연결되는지 설명한다."
        },
        "expectedEvidence": [
          "세탁소 요청을 정리해 요구사항 범위를 조정한 근거",
          "범위 판단을 뒷받침한 인터뷰 내용",
          "판단 근거와 포함·제외 범위의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨을 때, 세탁소 5곳의 요청을 정리해 요구사항 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "한 사례를 중심으로 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인터뷰에서 파악한 요청의 목적이나 필요성을 구체적으로 짚어 요구사항 범위 조정의 근거를 설명한다.",
            "그 근거로 어떤 요청을 포함하거나 제외했는지 설명하며 범위 판단의 일관성을 보여준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청의 필요성이나 구현 여건을 범위 조정의 근거로 제시하지만 설명이 일반적이다.",
            "근거와 포함·제외 범위를 연결하지만 인터뷰 내용과의 연결이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다는 사실만 반복하고 범위를 조정한 근거를 제시하지 못한다.",
            "범위 판단과 관계없는 문서 형식이나 도구 사용법을 설명하거나 요청과 무관한 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능의 예외 상황을 화면 흐름과 상태 변화에 연결해 설계할 수 있는지 확인한다. 예외가 발생했을 때 사용자가 보게 될 화면과 이어질 흐름을 정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 기획 담당으로 참여했다.",
          "task": "Figma로 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "action": "예약·취소·알림 중 구체적인 예외 상황을 들어 화면 흐름을 정한 근거를 설명한다.",
          "result": "그 근거가 화면 상태, 다음 행동, 안내 문구를 해석하는 데 어떤 차이를 만드는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황에 맞춰 화면 흐름을 정한 근거",
          "판단의 전제가 된 구체적인 예외 상황",
          "판단 근거와 화면 상태 또는 안내 문구의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예약·취소·알림의 예외 상황에 맞춰 화면 흐름을 정한 근거는 무엇이었나요?",
      "answerTip": "떠올린 사례를 짧게 소개하고 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구체적인 예외 상황에서 사용자가 겪을 문제를 짚어 화면 흐름을 정한 근거를 설명한다.",
            "설명한 근거가 화면 상태나 안내 문구에 연결되어 개발·디자인 담당자가 예외 흐름을 명확히 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황에 맞춘 화면 흐름의 근거를 제시하지만 사용자 혼란을 줄인다는 수준으로 설명이 일반적이다.",
            "근거와 화면 흐름을 연결하지만 예외 발생 시 화면 상태나 안내의 의미가 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실만 반복하고 화면 흐름을 정한 근거를 설명하지 못한다.",
            "예외 상황과 관계없는 화면 배치 취향이나 도구 기능만 설명해 화면 흐름 판단을 뒷받침하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 확인에서 의심스러운 용량을 발견했을 때 임의로 투약하지 않고 담당자에게 확인할 수 있는지 평가한다. 평소와 다른 용량을 투약 중단과 담당의 확인으로 연결한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력되어 있었다.",
          "task": "수술 전후 환자의 투약·처치를 담당했으며, 해당 처방은 투약 전에 확인했다.",
          "action": "평소와 다른 용량에서 무엇을 의심했으며, 투약을 진행하거나 임의로 용량을 바꾸지 않고 담당의에게 확인하기로 한 근거를 설명한다.",
          "result": "담당의 확인으로 입력 오류를 확인한 사실을 판단 근거와 연결해 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인하기로 판단한 근거",
          "처방을 의심하게 한 평소 용량과 입력 용량의 차이",
          "담당의 확인에서 밝혀진 입력 오류"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배였을 때, 투약을 멈추고 담당의에게 확인하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "한 사례를 중심으로 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량의 두 배라는 차이를 처방의 정확성을 다시 확인해야 할 구체적인 신호로 설명한다.",
            "처방의 타당성을 확인하지 못한 상태에서 투약하거나 임의로 용량을 조정하지 않고 담당의 확인이 필요하다고 판단한 근거를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량이어서 투약을 멈추고 확인했다고 답하지만, 무엇이 의심스러웠는지 설명이 구체적이지 않다.",
            "담당의 확인이 필요하다는 판단은 제시하지만, 확인 전 투약을 보류해야 했던 이유는 일반적인 안전 원칙 수준으로 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "실제로 투약을 멈추고 확인한 판단 근거 대신 투약 시 주의해야 한다는 일반론만 말한다.",
            "의심스러운 처방도 그대로 투약하거나 평소 용량으로 임의 조정해도 된다는 설명으로 당시 판단을 정당화한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
